                        <main class="main">
                                <div id="candidates" class="content-list__content"
                                        style="display: flex; flex-wrap: wrap; justify-content: space-between;">
                                        <h2 class="content-list__districts_title">Редактировать округа</h2>
                                </div>
                                <div class="districts-grid">

                                </div>

                                <script>
                                        (async function () {
                                                const grid = document.querySelector('.districts-grid');
                                                if (!grid) return;
                                                // тянем округа из контроллера: /districts?format=json
                                                const res = await fetch('/districts?format=json');
                                                const data = await res.json();   // ожидаем массив округов

                                                // индекс по id для удобства
                                                const byDistrict = {};
                                                data.forEach(d => {
                                                        const num = Number(d.district); // ВАЖНО!
                                                        if (!Number.isNaN(num)) byDistrict[num] = d;
                                                });

                                                // рисуем Округ 1..40
                                                for (let i = 1; i <= 40; i++) {
                                                        const d = byDistrict[i];

                                                        const a = document.createElement('a');
                                                        a.textContent = `Округ ${i}`;
                                                        a.classList.add('district');

                                                        if (d) {
                                                                // округ есть в БД → активная ссылка
                                                                a.classList.add('district--active');
                                                                a.href = `/district/admin/${i}`;   // или /district.php?id=${i} — как у тебя заведено
                                                        } else {
                                                                // округа нет в БД → «пустой» (но всё равно показываем)
                                                                a.classList.add('district--empty');
                                                                a.href = '#';
                                                                a.setAttribute('aria-disabled', 'true');
                                                        }

                                                        grid.appendChild(a);
                                                }
                                        })();
                                </script>
                        </main>
                </div>

